// Ícones do app (PNG), servidos em /icons/<nome>.png (ver rewrite no vercel.json).
const ICONS = {"apple-touch-icon.png":"","favicon-32.png":"","icon-192.png":"","icon-512.png":"","icon-maskable-512.png":""};

export default function handler(req, res) {
  const nome = String(req.query.n || '');
  const b64 = ICONS[nome];
  if (!b64) { res.statusCode = 404; return res.end(); }
  res.statusCode = 200;
  res.setHeader('Content-Type', 'image/png');
  res.setHeader('Cache-Control', 'public, max-age=86400');
  res.end(Buffer.from(b64, 'base64'));
}
